def f(m, i, k):
    #print(m[i][k])
    #input()
    if i < 19 or k < 19:
        if m[i][k][1] == 1 and m[i][k][2] == 1:
            #if max -> '-100000000000'
            return 100000000
        elif m[i][k][1] == 0 and m[i][k][2] == 1:
            return f(m, i + 1, k) + m[i][k][0]
        elif m[i][k][1] == 1 and m[i][k][2] == 0:
            return f(m, i, k + 1) + m[i][k][0]
        else:
            #or 'max'
            return min(f(m, i + 1, k) + m[i][k][0], f(m, i, k + 1) + m[i][k][0])
    elif i > 19 or k > 19:
        print('error')
    else:
        return m[i][k][0]

